/* R1366 — Spanish parity for the member-tools workspace and dynamic promotion controls */
(()=>{'use strict';
const D={
'Community Member tools':'Herramientas para Miembros de la Comunidad','Manage the features residents can see on your Franklin profile.':'Administre las funciones que los residentes pueden ver en su perfil de Franklin.','Use one workspace for richer profile media, coupons and specials, sales and promotions, events, and reviewed promotional graphics or flyers. Free profile claiming, factual corrections, removal and approved basic profile image/logo management remain free.':'Use un solo espacio para contenido multimedia del perfil, cupones y ofertas especiales, ventas y promociones, eventos y gráficos o volantes promocionales revisados. Reclamar el perfil, corregir datos, solicitar el retiro y administrar la imagen o logotipo básico aprobado siguen siendo gratuitos.','Choose what you want to manage':'Elija lo que desea administrar','Profile media':'Contenido multimedia del perfil','Manage your free approved profile image/logo plus Community Member cover and gallery media.':'Administre su imagen o logotipo básico aprobado de forma gratuita, además de la portada y galería para Miembros de la Comunidad.','Manage profile media':'Administrar contenido multimedia del perfil','Coupons & specials':'Cupones y ofertas especiales','Create reviewed coupon or special-offer details, codes, dates, links and promotional graphics.':'Cree cupones u ofertas especiales revisadas con detalles, códigos, fechas, enlaces y gráficos promocionales.','Manage coupons & specials':'Administrar cupones y ofertas especiales','Sales & promotions':'Ventas y promociones','Publish reviewed sale or promotion details with dates, calls to action and promotional graphics.':'Publique ventas o promociones revisadas con fechas, llamadas a la acción y gráficos promocionales.','Manage sales & promotions':'Administrar ventas y promociones','Events':'Eventos','Create reviewed event details, dates, location information and event-flyer graphics.':'Cree eventos revisados con detalles, fechas, ubicación y gráficos de volantes para eventos.','Manage events':'Administrar eventos','Create or edit':'Crear o editar','Coupon, special, sale, promotion or event':'Cupón, oferta especial, venta, promoción o evento','Type':'Tipo','Coupon':'Cupón','Special offer':'Oferta especial','Sale':'Venta','Promotion':'Promoción','Event':'Evento','Title':'Título','Description':'Descripción','Promo or coupon code':'Código promocional o de cupón','Discount or value text':'Descuento o valor','Starts':'Comienza','Ends / expires':'Termina / vence','Event location':'Ubicación del evento','Public action link':'Enlace público de acción','Save draft':'Guardar borrador','Save changes':'Guardar cambios','Clear form':'Limpiar formulario','Your current items':'Sus elementos actuales','Offers, promotions and events':'Ofertas, promociones y eventos','Promotional graphics & flyers':'Gráficos y volantes promocionales','Add a reviewed graphic to an offer, promotion or event':'Añada un gráfico revisado a una oferta, promoción o evento','Choose item':'Elegir elemento','Graphic type':'Tipo de gráfico','Coupon graphic':'Gráfico de cupón','Sale graphic':'Gráfico de venta','Promotional graphic':'Gráfico promocional','Promotional flyer':'Volante promocional','Event flyer':'Volante de evento','Image or PDF':'Imagen o PDF','Upload & submit for review':'Subir y enviar para revisión','I own this image or document or have permission to publish it.':'Soy propietario de esta imagen o documento o tengo permiso para publicarlo.','What happens after you submit?':'¿Qué sucede después de enviar?','Franklin reviews member-submitted promotional content and media before publication. Expired offers/events stop appearing publicly. If Community Membership becomes inactive, these paid promotional items fail closed and stop appearing publicly. Your free profile rights remain separate.':'Franklin revisa el contenido promocional y los archivos enviados por miembros antes de publicarlos. Las ofertas o eventos vencidos dejan de aparecer públicamente. Si la Membresía Comunitaria queda inactiva, estos elementos promocionales de pago dejan de mostrarse. Sus derechos gratuitos sobre el perfil permanecen separados.','Loading your member tools…':'Cargando sus herramientas de miembro…','No Franklin profile is connected to this account yet.':'Aún no hay un perfil de Franklin conectado a esta cuenta.','Find or connect my profile':'Buscar o conectar mi perfil','Choose the profile you want to manage':'Elija el perfil que desea administrar','Profile access is not verified yet. Complete free profile verification before using member tools.':'El acceso al perfil aún no está verificado. Complete la verificación gratuita del perfil antes de usar las herramientas para miembros.','Complete profile access':'Completar acceso al perfil','No coupons, promotions or events yet. Use the form above to create your first draft.':'Aún no hay cupones, promociones ni eventos. Use el formulario anterior para crear su primer borrador.','Edit':'Editar','Submit for review':'Enviar para revisión','Unpublish':'Retirar de publicación','Remove':'Eliminar','Add graphic / flyer':'Añadir gráfico / volante','Changes saved as a draft.':'Cambios guardados como borrador.','Draft created.':'Borrador creado.','Submitted for review.':'Enviado para revisión.','Item removed.':'Elemento eliminado.','Graphic uploaded and submitted for review.':'Gráfico subido y enviado para revisión.','PDF uploaded and submitted for review.':'PDF subido y enviado para revisión.','No promotional graphics or flyers submitted yet.':'Aún no se han enviado gráficos ni volantes promocionales.','Sign in through Member Account to use these tools.':'Inicie sesión en su cuenta de miembro para usar estas herramientas.','Verify management access for this profile before using Community Member tools.':'Verifique el acceso de administración de este perfil antes de usar las herramientas para miembros.','An active Community Membership is required for coupons, promotions, events and promotional graphics.':'Se requiere una Membresía Comunitaria activa para cupones, promociones, eventos y gráficos promocionales.','This item changed in another session. Reload and try again.':'Este elemento cambió en otra sesión. Vuelva a cargar e inténtelo de nuevo.','This item is waiting for review.':'Este elemento está pendiente de revisión.','This graphic is waiting for review.':'Este gráfico está pendiente de revisión.','The member service is temporarily unavailable. Please try again.':'El servicio para miembros no está disponible temporalmente. Inténtelo de nuevo.','We could not complete that request.':'No pudimos completar esa solicitud.','Choose an image.':'Elija una imagen.','Choose a standard PDF document.':'Elija un documento PDF estándar.','Confirm you own this document or have permission to publish it.':'Confirme que es propietario de este documento o tiene permiso para publicarlo.','Choose the Franklin profile you want to manage.':'Elija el perfil de Franklin que desea administrar.','Choose the offer, promotion or event for this document.':'Elija la oferta, promoción o evento para este documento.','PDF flyers and coupons must be 4 MB or smaller.':'Los volantes y cupones en PDF deben tener un tamaño máximo de 4 MB.','Uploading PDF for review…':'Subiendo PDF para revisión…','JPG/JPEG, PNG and WebP images are prepared as WebP before upload. PDFs are accepted as reviewed documents. Maximum 4 MB; PDFs may contain up to 20 pages and may not contain active scripts, forms, embedded files or encryption.':'Las imágenes JPG/JPEG, PNG y WebP se preparan como WebP antes de subirlas. Los PDF se aceptan como documentos revisados. Máximo 4 MB; los PDF pueden tener hasta 20 páginas y no pueden contener scripts activos, formularios, archivos incrustados ni cifrado.'
};
const originals=new WeakMap();
function lang(){return window.FranklinI18n?.language==='es'||localStorage.getItem('franklinLanguage')==='es'?'es':'en'}
function eligible(n){const p=n.parentElement;if(!p)return false;if(p.closest('script,style,textarea,code,pre'))return false;if(p.closest('.r1365-item h3,.r1365-item>p:not(.fine-print)'))return false;return true}
function translateText(n){if(n.nodeType!==Node.TEXT_NODE||!eligible(n))return;if(!originals.has(n))originals.set(n,n.nodeValue);const raw=originals.get(n),trim=String(raw).trim();if(lang()==='es'&&D[trim])n.nodeValue=String(raw).replace(trim,D[trim]);else if(lang()==='en')n.nodeValue=raw;else if(lang()==='es'){
 let m=trim.match(/^Loading (.+)…$/);if(m)n.nodeValue=String(raw).replace(trim,`Cargando ${m[1]}…`);
 m=trim.match(/^Community Member tools are ready for (.+)\.$/);if(m)n.nodeValue=String(raw).replace(trim,`Las herramientas para miembros están listas para ${m[1]}.`);
 if(/ — access not verified$/.test(trim))n.nodeValue=String(raw).replace(trim,trim.replace(/ — access not verified$/,' — acceso no verificado'));
 if(/^Ends /.test(trim))n.nodeValue=String(raw).replace(trim,trim.replace(/^Ends /,'Termina '));
 }
}
function walk(root){if(root.nodeType===Node.TEXT_NODE)return translateText(root);if(root.nodeType!==Node.ELEMENT_NODE)return;const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let n;while(n=w.nextNode())translateText(n)}
function apply(){walk(document.body)}
document.addEventListener('DOMContentLoaded',()=>{apply();document.querySelectorAll('[data-r37-lang]').forEach(b=>b.addEventListener('click',()=>setTimeout(apply,0)));new MutationObserver(rs=>{for(const r of rs){if(r.type==='characterData')translateText(r.target);for(const n of r.addedNodes)walk(n)}}).observe(document.body,{subtree:true,childList:true,characterData:true});});
})();
